#!/bin/bash
# Draws the six pictures for the sample story "Rafi goes to the barber" (one sheet of six panels).
# Run once the picture key works:  bash tools/make-art.sh   then press "Reset demo" in the pitch view.
cd "$(dirname "$0")/../public/art" || exit 1
~/.local/bin/neoimg "A sheet of exactly six square illustration panels arranged in a precise grid of 3 columns and 2 rows, all panels exactly the same size, separated by thin straight white gutters, with a thin white border around the sheet. No text, no letters, no numbers, no captions anywhere. Style for every panel: soft rounded 3D clay illustration for a young children's picture book, simple and uncluttered, calm pastel colours with gentle mint-green and warm cream tones, soft even light, clear literal scenes that are easy to understand. The same boy appears in every panel and must look identical each time: Rafi, a 5-year-old Bangladeshi boy with warm brown skin, short black hair that is a bit long and messy over his forehead, a simple friendly face with small dot eyes, wearing a plain yellow t-shirt and blue shorts, often holding a small red toy train. His mother: a Bangladeshi woman with a long black braid wearing a teal salwar kameez. The barber: a kind man with a short beard wearing a white apron. Panel 1 (top left): Rafi at home looking in a mirror, touching his long messy hair, his mother beside him smiling. Panel 2 (top middle): inside a small tidy barbershop, Rafi sits on a waiting bench next to his mother, calmly holding his red toy train, while another child gets a haircut in the background. Panel 3 (top right): Rafi sitting in the big barber chair while the kind barber gently puts a light-blue cape around his shoulders. Panel 4 (bottom left): the barber holds an electric hair clipper with small soft curved sound lines coming from it; Rafi in the chair squeezes his red toy train and takes a slow deep breath, staying calm, his mother holding his other hand. Panel 5 (bottom middle): the barber carefully cutting Rafi's hair with the clipper, Rafi sitting still and calm in the cape, small bits of hair falling. Panel 6 (bottom right): Rafi with a neat short new haircut smiling proudly at himself in the barbershop mirror, his mother clapping happily beside him." -q high -k 2k -r 3:2 -o story-barber.png
